<?php /** @var array<string,mixed> $project */ /** @var list<array<string,mixed>> $items */ /** @var array{done:int,total:int} $progress */ /** @var bool $staff */ /** @var bool $canEdit */ /** @var bool $canApply */ /** @var list<array<string,mixed>> $templates */ /** @var list<array<string,mixed>> $versions */ use Vertex\Core\View;
$u = '/projects/' . $project['public_id'] . '/checklist'; ?>
<div class="page-head"><div><p class="eyebrow"><a href="/projects/<?= e($project['public_id']) ?>"><?= e($project['code']) ?></a></p><h1><?= e($project['title']) ?></h1></div></div>
<?= View::partial('project-tabs', ['project' => $project, 'tab' => 'checklist']) ?>
<div class="panel"><h2>Checklist <span class="muted">(<?= (int) $progress['done'] ?> of <?= (int) $progress['total'] ?> done)</span></h2>
    <?php if ($items === []) : ?><p class="muted">No checklist yet.</p><?php endif; ?>
    <ul class="plain"><?php foreach ($items as $i) : ?><li><?= $i['done_at'] ? '<span class="badge">done</span> ' : '' ?><?= (int) $i['in_scope'] === 0 ? '<span class="badge">out of scope</span> ' : '' ?><strong><?= e($i['title']) ?></strong>
        <?php if ($i['done_at']) : ?><br><span class="muted">Done <?= e(local_time($i['done_at'])) ?><?= $i['done_by_name'] && $staff ? ' by ' . e($i['done_by_name']) : '' ?><?= $i['deliverable_title'] ? ' · delivered in ' . e($i['deliverable_title']) . ' v' . (int) $i['version_no'] : '' ?></span><?php endif; ?>
        <?php if ($canEdit) : ?><form method="post" action="<?= e($u) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="item" value="<?= (int) $i['id'] ?>">
            <?php if (!$i['done_at']) : ?><select name="version" aria-label="Delivered in"><option value="">(no version)</option><?php foreach ($versions as $v) : ?><option value="<?= (int) $v['id'] ?>"><?= e($v['title']) ?> v<?= (int) $v['version_no'] ?></option><?php endforeach; ?></select><button class="btn btn-ghost btn-sm" name="action" value="done" type="submit">Done</button><?php else : ?><button class="btn btn-ghost btn-sm" name="action" value="undo" type="submit">Undo</button><?php endif; ?>
            <button class="btn btn-ghost btn-sm" name="action" value="<?= (int) $i['in_scope'] === 1 ? 'out_of_scope' : 'in_scope' ?>" type="submit"><?= (int) $i['in_scope'] === 1 ? 'Out of scope' : 'Back in scope' ?></button><button class="btn btn-ghost btn-sm" name="action" value="delete" type="submit">Remove</button></form><?php endif; ?></li><?php endforeach; ?></ul>
    <?php if ($canEdit) : ?><form method="post" action="<?= e($u) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="add"><div class="field"><label for="t">Add a point</label><input id="t" name="title" required maxlength="200"></div><div class="form-actions"><button class="btn btn-primary btn-sm" type="submit">Add</button></div></form><?php endif; ?></div>
<?php if ($canApply && $templates !== []) : ?><div class="panel"><h2>Apply a template</h2><form method="post" action="<?= e($u) ?>" class="form-grid" data-confirm="Create the template's milestones, tasks and checklist points in this project?"><?= csrf_field() ?><input type="hidden" name="action" value="apply">
    <div class="field"><label for="tp">Template</label><select id="tp" name="template" required><option value="">Choose…</option><?php foreach ($templates as $t) : ?><option value="<?= e($t['public_id']) ?>"><?= e($t['name']) ?> (<?= (int) $t['items'] ?> lines)</option><?php endforeach; ?></select></div>
    <div class="field"><label class="check"><input type="checkbox" name="confirm" value="1"> This project already has work: add the template's items as well</label></div>
    <div class="form-actions"><button class="btn btn-primary" type="submit">Apply template</button></div></form></div><?php endif; ?>
